describe('Data Tables Responsive Stacking on Small Screens', () => {
  beforeEach(() => {
    cy.visit('/data-tables');
  });

  it('should stack data tables vertically on small screens', () => {
    // Verify initial state: data tables are horizontal on medium screens
    cy.get('[data-testid="data-table-container"]').should('be.visible');
    cy.get('[data-testid="data-table-1"]').should('be.visible');
    cy.get('[data-testid="data-table-2"]').should('be.visible');
    cy.get('[data-testid="data-table-1"]').should('have.css', 'width', '600px');
    cy.get('[data-testid="data-table-2"]').should('have.css', 'width', '600px');

    // Navigate to mobile view
    cy.viewport('iphone-x');

    // Verify data tables stack vertically
    cy.get('[data-testid="data-table-container"]').should('have.css', 'flex-direction', 'column');
    cy.get('[data-testid="data-table-1"]').should('have.css', 'flex-basis', '100%');
    cy.get('[data-testid="data-table-2"]').should('have.css', 'flex-basis', '100%');

    // Verify table headers are visible and not overlapping
    cy.get('[data-testid="data-table-1"]').get('[data-testid="table-header"]').should('be.visible');
    cy.get('[data-testid="data-table-2"]').get('[data-testid="table-header"]').should('be.visible');

    // Verify table rows are visible and not overlapping
    cy.get('[data-testid="data-table-1"]').get('[data-testid="table-row"]').should('be.visible');
    cy.get('[data-testid="data-table-2"]').get('[data-testid="table-row"]').should('be.visible');

    // Verify pagination controls are visible and functional
    cy.get('[data-testid="data-table-pagination"]').should('be.visible');
    cy.get('[data-testid="data-table-pagination-button"]').should('be.visible');
    cy.get('[data-testid="data-table-pagination-button"]').click();
    cy.get('[data-testid="data-table-pagination-button"]').should('be.visible');

    // Verify sorting functionality is still available
    cy.get('[data-testid="data-table-sort-button"]').should('be.visible');
    cy.get('[data-testid="data-table-sort-button"]').click();
    cy.get('[data-testid="data-table-sort-button"]').should('be.visible');

    // Verify search functionality is still available
    cy.get('[data-testid="data-table-search-input"]').should('be.visible');
    cy.get('[data-testid="data-table-search-input"]').type('test');
    cy.get('[data-testid="data-table-search-input"]').should('have.value', 'test');

    // Verify table footer is visible and displays correct information
    cy.get('[data-testid="data-table-footer"]').should('be.visible');
    cy.get('[data-testid="data-table-footer"]').should('contain', 'Total Records');

    // Navigate back to medium screen
    cy.viewport('desktop');

    // Verify data tables are horizontal again
    cy.get('[data-testid="data-table-container"]').should('have.css', 'flex-direction', 'row');
    cy.get('[data-testid="data-table-1"]').should('have.css', 'width', '600px');
    cy.get('[data-testid="data-table-2"]').should('have.css', 'width', '600px');
  });

  it('should handle edge case: data tables overflow container on small screens', () => {
    // Navigate to small screen
    cy.viewport('iphone-x');

    // Load data tables with large datasets
    cy.intercept('GET', '/api/data-tables/1').as('loadDataTables');
    cy.wait('@loadDataTables');

    // Verify data tables are stacked vertically
    cy.get('[data-testid="data-table-container"]').should('have.css', 'flex-direction', 'column');

    // Verify overflow is handled gracefully
    cy.get('[data-testid="data-table-1"]').should('have.css', 'overflow-y', 'auto');
    cy.get('[data-testid="data-table-2"]').should('have.css', 'overflow-y', 'auto');

    // Verify scrollable content is available
    cy.get('[data-testid="data-table-1"]').scrollTo('bottom');
    cy.get('[data-testid="data-table-1"]').should('be.visible');

    // Verify pagination controls are still visible and functional
    cy.get('[data-testid="data-table-pagination"]').should('be.visible');
    cy.get('[data-testid="data-table-pagination-button"]').should('be.visible');

    // Verify sorting functionality is still available
    cy.get('[data-testid="data-table-sort-button"]').should('be.visible');
    cy.get('[data-testid="data-table-sort-button"]').click();
    cy.get('[data-testid="data-table-sort-button"]').should('be.visible');

    // Verify search functionality is still available
    cy.get('[data-testid="data-table-search-input"]').should('be.visible');
    cy.get('[data-testid="data-table-search-input"]').type('test');
    cy.get('[data-testid="data-table-search-input"]').should('have.value', 'test');

    // Verify table footer is still visible and displays correct information
    cy.get('[data-testid="data-table-footer"]').should('be.visible');
    cy.get('[data-testid="data-table-footer"]').should('contain', 'Total Records');

    // Navigate back to medium screen
    cy.viewport('desktop');

    // Verify data tables are horizontal again
    cy.get('[data-testid="data-table-container"]').should('have.css', 'flex-direction', 'row');
    cy.get('[data-testid="data-table-1"]').should('have.css', 'width', '600px');
    cy.get('[data-testid="data-table-2"]').should('have.css', 'width', '600px');
  });
});
